source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def edge_runs(color, side):
        if side in ("left", "right"):
            c = 0 if side == "left" else w - 1
            vals = [grid[r][c] for r in range(h)]
        else:
            r = 0 if side == "top" else h - 1
            vals = grid[r][:]
        runs = []
        start = None
        for i, v in enumerate(vals + [None]):
            if v == color and start is None:
                start = i
            elif v != color and start is not None:
                if i - start >= 2:
                    runs.append((start, i))
                start = None
        return runs

    candidates = []
    for color in set(v for row in grid for v in row) - {bg}:
        for side_a, side_b in (("left", "right"), ("top", "bottom")):
            for a in edge_runs(color, side_a):
                for b in edge_runs(color, side_b):
                    candidates.append((min(a[1]-a[0], b[1]-b[0]),
                                      (a[1]-a[0])+(b[1]-b[0]), color,
                                      side_a, a, side_b, b))
    if not candidates:
        return [row[:] for row in grid]
    _, _, bar, side_a, run_a, side_b, run_b = max(candidates)
    other_colors = [v for v in set(v for row in grid for v in row) if v not in (bg, bar)]
    if not other_colors:
        return [row[:] for row in grid]
    dot = max(other_colors, key=lambda v: sum(x == v for row in grid for x in row))

    out = [row[:] for row in grid]
    def paint(r, c):
        if out[r][c] == bg:
            out[r][c] = dot

    def in_run(t, run):
        return run[0] <= t < run[1]

    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == dot]
    for r, c in cells:
        t = r if side_a in ("left", "right") else c
        if in_run(t, run_a):
            src_side, src_run, dst_side, dst_run = side_a, run_a, side_b, run_b
        elif in_run(t, run_b):
            src_side, src_run, dst_side, dst_run = side_b, run_b, side_a, run_a
        else:
            continue
        # Extend the marker back to the boundary segment it belongs to.
        if src_side == "left":
            for cc in range(1, c): paint(r, cc)
        elif src_side == "right":
            for cc in range(c + 1, w - 1): paint(r, cc)
        elif src_side == "top":
            for rr in range(1, r): paint(rr, c)
        else:  # bottom
            for rr in range(r + 1, h - 1): paint(rr, c)

        # Copy the ray at the same offset within the opposite boundary segment.
        t2 = t + dst_run[0] - src_run[0]
        if dst_side in ("left", "right"):
            for cc in range(1, w - 1): paint(t2, cc)
        else:
            for rr in range(1, h - 1): paint(rr, t2)

    for r, c in cells:
        out[r][c] = 4
    return out
'''
